{"implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        gain = (call['loss_without_call'] - call['loss_with_call']) / call['prediction_tokens']
        accept = call['parseable'] and gain >= threshold
        if accept:
            accepted_call_ids.append(call['call_id'])
        diagnostics.append({
            'accepted': accept,
            'call_id': call['call_id'],
            'normalized_gain': gain
        })
    return {'accepted_call_ids': accepted_call_ids, 'diagnostics': diagnostics}"}
